from grader import filter_passing_scores

def test_strictly_above():
    # Passes before fix
    assert filter_passing_scores([60, 70, 80], 50) == [60, 70, 80]

def test_boundary_score():
    assert filter_passing_scores([50], 50) == [50]

def test_mixed_scores():
    assert filter_passing_scores([49, 50, 51], 50) == [50, 51]

def test_empty_scores():
    assert filter_passing_scores([], 50) == []

